css:
.container {
  width: 100%;
  height: 100%;
  --s: 70px;
  --c1: #ff9a9e;
  --c2: #fad0c4;
  --c3: #2c3e50;

  background-color: var(--c3);
  background-image: linear-gradient(315deg, var(--c1) 25%, transparent 25%),
    linear-gradient(45deg, var(--c1) 25%, transparent 25%),
    linear-gradient(315deg, var(--c2) 25%, transparent 25%),
    linear-gradient(45deg, var(--c2) 25%, transparent 25%);
  background-size: calc(2 * var(--s)) var(--s);
  background-position:
    0 0,
    0 0,
    var(--s) calc(var(--s) / 2),
    var(--s) calc(var(--s) / 2);
}
